/* GALE — home: wake-cycle scrub, live pulse feed, spend & quota. */
import { boot, clamp, esc, raf, REDUCED, refreshEffects, whenPageActive } from "./shared.js";
import { initCinematic } from "./cinematic.js";
import { initStormScene } from "./storm-scene.js";
import { lazyHeartbeat } from "./heartbeat.js";

boot();
initCinematic();
initStormScene();

/* wire the shared effects engine to static markup: section reveals +
   count-up stat numbers (dynamic regions call refreshEffects themselves). */
document.querySelectorAll(".block:not(#hero)").forEach((el) => el.classList.add("reveal"));
document.querySelectorAll(".stat-num").forEach((el) => {
  if (/^[\d,]+$/.test(el.textContent.trim())) el.setAttribute("data-countup", "");
});
refreshEffects();

/* ---- wake cycle: scroll-scrubbed orbit. The four steps live in the HTML
   (#wake-steps); JS reads them out and drives the sticky SVG stage. ---- */
function buildWakeScrub() {
  const ol = document.getElementById("wake-steps");
  const mount = document.getElementById("wake-scrub");
  const section = document.getElementById("stats");
  if (!ol || !mount || !section || REDUCED) return;

  const items = [...ol.querySelectorAll("span")].map((s) => {
    const t = s.textContent.replace(/\s+/g, " ").trim();
    const m = t.match(/^\d+\s*·\s*(.*)$/);
    return { title: (m ? m[1] : t).trim(), body: "" };
  });
  if (items.length < 2) return;

  const dots = [
    [160, 42], [278, 160], [160, 278], [42, 160],
  ];

  mount.innerHTML = `
    <div class="wake-track">
      <div class="wake-stage">
        <div class="wake-copy-set">
          ${items
            .map(
              (it, i) => `
          <div class="wake-copy${i === 0 ? " on" : ""}">
            <div class="k">Step 0${i + 1} / 0${items.length}</div>
            <h3>${esc(it.title)}</h3>
          </div>`
            )
            .join("")}
          <div class="wake-bar" aria-hidden="true"><i></i></div>
        </div>
        <div class="wake-orbit" aria-hidden="true">
          <svg viewBox="0 0 320 320">
            <circle class="odash" cx="160" cy="160" r="141" />
            <circle class="oring" cx="160" cy="160" r="118" />
            <circle class="odraw" cx="160" cy="160" r="118" data-c="${(2 * Math.PI * 118).toFixed(2)}" />
            ${dots.map(([x, y]) => `<circle class="ostep" cx="${x}" cy="${y}" r="5.5" />`).join("")}
            <g class="otravel"><circle class="otraveller" cx="160" cy="42" r="5.5" /></g>
            <text class="onum" x="160" y="172" text-anchor="middle">01</text>
            <text class="osub" x="160" y="198" text-anchor="middle">OF 0${items.length}</text>
          </svg>
        </div>
      </div>
    </div>`;

  section.classList.add("scrub-live");
  mount.setAttribute("aria-hidden", "false");

  const track = mount.querySelector(".wake-track");
  const copies = [...mount.querySelectorAll(".wake-copy")];
  const stepDots = [...mount.querySelectorAll(".ostep")];
  const draw = mount.querySelector(".odraw");
  const num = mount.querySelector(".onum");
  const bar = mount.querySelector(".wake-bar i");
  const C = parseFloat(draw.dataset.c);
  draw.style.strokeDasharray = `${C}`;
  draw.style.strokeDashoffset = `${C}`;

  let current = -1;
  let pending = false;

  const update = () => {
    pending = false;
    const r = track.getBoundingClientRect();
    const total = r.height - window.innerHeight;
    const p = clamp(total > 0 ? -r.top / total : 0);
    draw.style.strokeDashoffset = `${(C * (1 - p)).toFixed(1)}`;
    const idx = Math.min(items.length - 1, Math.floor(p * items.length));
    if (idx === current) return;
    current = idx;
    copies.forEach((c, i) => c.classList.toggle("on", i === idx));
    stepDots.forEach((d, i) => d.classList.toggle("on", i <= idx));
    num.textContent = `0${idx + 1}`;
    bar.style.transform = `translateX(${idx * 100}%)`;
  };

  window.addEventListener("scroll", () => {
    if (!pending) { pending = true; raf(update); }
  }, { passive: true });
  update();
}
buildWakeScrub();
lazyHeartbeat();

/* fleet ops summary: the operations entry boots itself on import when
   #home-ops-summary exists (review 2026-10-11 #9). Load it lazily so index
   ships one entry script and boot() runs once; same pattern as lazyCadence. */
(function lazyOpsSummary() {
  const slot = document.getElementById("home-ops-summary");
  if (!slot) return;
  const load = () => import("./operations.js").catch(() => {});
  if (typeof IntersectionObserver !== "function") { load(); return; }
  const io = new IntersectionObserver((es) => {
    if (!es.some((e) => e.isIntersecting)) return;
    io.disconnect();
    load();
  }, { rootMargin: "500px 0px" });
  io.observe(slot);
})();

/* fleet cadence 3D: load when the section nears the viewport */
(function lazyCadence() {
  const sec = document.getElementById("cadence");
  if (!sec || typeof IntersectionObserver !== "function") return;
  const io = new IntersectionObserver((es) => {
    if (!es.some((e) => e.isIntersecting)) return;
    io.disconnect();
    import("./cadence3d.js").then((m) => m.initCadence3D()).catch(() => { sec.hidden = true; });
  }, { rootMargin: "500px 0px" });
  io.observe(sec);
})();

/* hovering/focusing an agent chip in the host cards focuses that agent in the 3D map above them */
(function chipFocus() {
  const grid = document.querySelector(".host-grid");
  if (!grid) return;
  const fire = (name) => window.dispatchEvent(new CustomEvent(name ? "gale:focus-agent" : "gale:focus-clear", { detail: { agent: name } }));
  grid.addEventListener("mouseover", (e) => { const a = e.target.closest && e.target.closest("a.agent"); if (a) fire(a.textContent.trim()); });
  grid.addEventListener("focusin", (e) => { const a = e.target.closest && e.target.closest("a.agent"); if (a) fire(a.textContent.trim()); });
  grid.addEventListener("mouseleave", () => fire(""));
  grid.addEventListener("focusout", () => fire(""));
})();

/* live 3D fleet map: load the WebGL module only when the fleet section nears the viewport */
(function lazyFleet3D() {
  const sec = document.getElementById("fleet"); // not #home-topo: it is display:none until WebGL opens
  if (!document.getElementById("home-topo") || !sec || typeof IntersectionObserver !== "function" || REDUCED) return;
  const io = new IntersectionObserver((es) => {
    if (!es.some((e) => e.isIntersecting)) return;
    io.disconnect();
    import("./topology3d.js").then((t) => t.initTopology3D({ autoOpen: true })).catch(() => {});
  }, { rootMargin: "500px 0px" });
  io.observe(sec);
})();

/* ---- §3 live pulse: last 8 mesh events, newest first ---- */
const KIND_ICON = { waking: "◇", backup: "▣", peer: "✉", "peer-flag": "⚠", commit: "◆", agora: "☰", relay: "⇄" };

function fmtAgo(iso) {
  const s = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 1000));
  if (!isFinite(s)) return "";
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return `${Math.floor(s / 86400)}d ago`;
}

let lastPulseSig = "";

export async function renderLivePulse(preloaded) {
  const feed = document.getElementById("pulse-feed");
  if (!feed) return;
  let d = preloaded;
  if (!d) {
    try {
      const r = await fetch("/api/fleet/activity", { cache: "no-store" });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      d = await r.json();
    } catch {
      feed.innerHTML = `<li class="pulse-row muted">feed unreachable — mesh offline or 8090 down</li>`;
      return;
    }
  }
  const events = (d.events || []).slice(-8).reverse();
  const sig = JSON.stringify(events);
  if (sig === lastPulseSig) return; // SSE pushes repeat payloads; don't re-render (or re-animate) them
  lastPulseSig = sig;
  if (!events.length) {
    feed.innerHTML = `<li class="pulse-row muted">mesh quiet — no recent wakes</li>`;
    return;
  }
  feed.innerHTML = events.map((ev) => `
    <li class="pulse-row">
      <span class="pulse-kind">${esc(KIND_ICON[ev.kind] || "·")}</span>
      <span class="pulse-agent">${esc((ev.agent || "?").toUpperCase())}</span>
      <span class="pulse-text">${esc(ev.text || "")}</span>
      <span class="pulse-ago">${esc(fmtAgo(ev.ts))}</span>
    </li>`).join("");
  renderHistory(d);
  renderWakeDots(d.events || []);
}
renderLivePulse();

/* ---- live push: the SSE stream re-renders the pulse feed the moment a mesh
   event lands and tells the 3D fleet map (topology3d.js listens for
   gale:activity-event) to ripple from that agent instantly, instead of the
   map waiting for its own 15 s REST poll (which remains as the fallback).
   If EventSource is missing or the stream dies repeatedly, the one-shot
   fetch above is the floor; a slow poll keeps the feed from going stale. ---- */
(function pulseSSE() {
  if (typeof EventSource === "undefined") { startPulsePoll(); return; }
  whenPageActive().then(() => { // don't open streams from a prerendering page
  let seen = null, failures = 0, dead = false;
  try {
    const es = new EventSource("/api/fleet/activity/stream");
    es.onmessage = (e) => {
      failures = 0;
      let d;
      try { d = JSON.parse(e.data); } catch { return; } // malformed payload -- wait for the next push
      const evs = (d.events || []).slice().sort((a, b) => String(a.ts).localeCompare(String(b.ts)));
      if (seen === null) seen = evs.length ? evs[evs.length - 1].ts : ""; // first push: sync, no ripple backlog
      else {
        let n = 0;
        for (const ev of evs) {
          if (!ev.ts || String(ev.ts) <= seen) continue;
          if (n++ < 6) window.dispatchEvent(new CustomEvent("gale:activity-event", { detail: { agent: ev.agent, host: ev.host, kind: ev.kind, ts: ev.ts } }));
        }
        if (evs.length) seen = evs[evs.length - 1].ts;
      }
      renderLivePulse(d);
    };
    es.onerror = () => {
      if (++failures >= 3 && !dead) { // stream gone (proxy won't stream) -- stop hammering, poll slowly
        dead = true;
        es.close();
        startPulsePoll();
      }
    };
  } catch { startPulsePoll(); } // construction failure used to leave the feed one-shot forever (#66)
  });
})();

// slow fallback poll shared by the SSE error path and the no-EventSource path
// (#66): also refreshes the one-shot roster facts + spend bars, which used to
// never update again after their initial fetch
function startPulsePoll() {
  if (window.__galePulsePoll) return;
  window.__galePulsePoll = setInterval(() => {
    if (document.hidden) return;
    renderLivePulse();
    renderRosterFacts();
    renderSpend();
  }, 60000);
}

/* ---- model composition chips + open-ask count: derived from live registry
   and asks feeds (review 2026-10-11 #40/#41). The static markup stays as the
   no-JS fallback -- it had drifted (Qwen x13 missing, Muse x12 vs x2). ---- */
export async function renderRosterFacts() {
  const chips = document.querySelector(".chips[aria-label='Model composition']");
  if (chips) {
    try {
      const r = await fetch("/api/fleet/registry", { cache: "no-store" });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const agents = (await r.json()).agents || [];
      const counts = new Map();
      for (const a of agents) {
        const model = String(a.model || "unknown");
        counts.set(model, (counts.get(model) || 0) + 1);
      }
      if (counts.size) {
        chips.innerHTML = [...counts.entries()]
          .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
          .map(([model, n]) => `<li class="chip" data-model="${esc(model.toLowerCase())}">${esc(model)} &times;${n}</li>`)
          .join("");
      }
    } catch { /* static fallback stands */ }
  }
  const askBar = document.querySelector("#ask .redact-bar");
  if (askBar) {
    try {
      const r = await fetch("/api/fleet/asks", { cache: "no-store" });
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      const agents = (await r.json()).agents || [];
      const open = agents.reduce((sum, a) => sum + (Number(a.open_asks) || 0), 0);
      askBar.textContent = `${open} open item${open === 1 ? "" : "s"} — ask me.`;
    } catch { /* static count stands */ }
  }
}

/* ---- recent history: latest commits from the same activity feed.
   Static 2026-09-23 list in markup stays as the no-JS fallback. ---- */
export function renderHistory(d) {
  const list = document.querySelector(".history-list");
  if (!list) return;
  const commits = (d.events || []).filter((ev) => ev.kind === "commit").slice(-8).reverse();
  if (!commits.length) return;
  list.innerHTML = commits.map((ev) => {
    const msg = String(ev.text || "").split(" -- ").slice(1).join(" -- ") || ev.text || "";
    const day = (ev.ts || "").slice(0, 10);
    return `<li><span class="h-time"><time datetime="${esc(ev.ts || "")}">${esc(day)}</time></span>` +
      `<span class="h-msg">${esc(msg.slice(0, 140))}</span></li>`;
  }).join("");
}

/* ---- wake-activity dot strip (#4): last 24h bucketed by hour; a filled
   dot means at least one mesh event that hour. Same activity feed, no new
   requests. ---- */
export function renderWakeDots(events) {
  const box = document.getElementById("wake-dots");
  if (!box) return;
  const nowH = Math.floor(Date.now() / 3600e3);
  const counts = new Array(24).fill(0);
  for (const ev of events) {
    const t = new Date(ev.ts || 0).getTime();
    if (!Number.isFinite(t)) continue;
    const h = Math.floor(t / 3600e3);
    const back = nowH - h;
    if (back >= 0 && back < 24) counts[23 - back] += 1;
  }
  const max = Math.max(...counts, 1);
  const busyH = counts.indexOf(Math.max(...counts));
  const busyHr = new Date((nowH - (23 - busyH)) * 3600e3).getHours();
  // per-dot labels + a text summary (#67): the data was title-only, invisible
  // to screen readers
  box.innerHTML = counts.map((c, i) => {
    const lvl = c === 0 ? "" : c >= max && max > 2 ? "hot" : "on";
    const hr = new Date((nowH - (23 - i)) * 3600e3).getHours();
    return `<i class="wake-dot${lvl ? ` ${lvl}` : ""}" title="${hr}:00 — ${c} event${c === 1 ? "" : "s"}" aria-label="${hr}:00, ${c} event${c === 1 ? "" : "s"}"></i>`;
  }).join("") + `<span class="wake-dots-label">24h wake activity · ${events.length} events · busiest ${busyH}:00 with ${counts[busyH]}</span>`;
}

/* ---- §12 spend & quota: cost by host + busiest agents, last 24h ---- */
const HOST_COLOR = { gale: "var(--m-glm)", beacon: "var(--m-claude)", tidal: "#3fc7ff", mountain: "var(--m-muse)" };

export async function renderSpend() {
  const bars = document.getElementById("spend-bars");
  const agents = document.getElementById("spend-agents");
  if (!bars || !agents) return;
  try {
    const r = await fetch("/api/fleet/metrics", { cache: "no-store" });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    const d = await r.json();

    const totals = Object.entries(d.daily_cost_by_host || {})
      .map(([h, series]) => [h, series.reduce((s, v) => s + (v || 0), 0)])
      .sort((a, b) => b[1] - a[1]);
    const max = Math.max(...totals.map(([, v]) => v), 0.000001);
    bars.innerHTML = totals.length
      ? totals.map(([h, v]) => `
        <div class="spend-row">
          <span class="spend-host"><a href="metrics.html">${esc(h)}</a></span>
          <span class="spend-track"><i style="width:${(v / max * 100).toFixed(1)}%;background:${HOST_COLOR[h] || "var(--flag)"}"></i></span>
          <span class="spend-val">$${v.toFixed(2)}</span>
        </div>`).join("")
      : `<span class="muted">no cost data yet</span>`;

    // 14-day fleet spend trend (#4): daily totals across hosts into the
    // shared sparkline, day labels for the hover readout.
    const spark = document.getElementById("spend-spark");
    if (spark && typeof spark.update === "function" && Array.isArray(d.days)) {
      const perDay = d.days.map((_, i) =>
        Object.values(d.daily_cost_by_host || {}).reduce((s, srs) => s + (srs[i] || 0), 0));
      spark.update([perDay], [{ color: "#ffc233", fill: "rgba(255,194,51,.14)", width: 1.8 }], {
        labels: d.days.map((day) => day.slice(5)),
        tipFmt: (i, vals, label) => `${label || ""} · fleet $${(vals[0] || 0).toFixed(2)}`,
      });
    }

    const top = [...(d.per_agent_24h || [])]
      .sort((a, b) => b.cost_24h - a.cost_24h)
      .slice(0, 6);
    agents.innerHTML = top.length
      ? top.map((a) => `
        <li class="spend-agent-row">
          <span class="spend-agent-name">${esc(a.agent || "?")}</span>
          <span class="spend-agent-runs">${a.runs_24h} run${a.runs_24h === 1 ? "" : "s"}</span>
          <span class="spend-agent-cost">$${(a.cost_24h ?? 0).toFixed(4)}</span>
        </li>`).join("")
      : `<li class="muted">no agent activity in the last 24h</li>`;
  } catch {
    bars.innerHTML = `<span class="muted">spend feed unreachable</span>`;
    agents.innerHTML = `<li class="muted">spend feed unreachable</li>`;
  }
}
renderSpend();
renderRosterFacts();

/* ---- home special effects (off for reduced motion / data-saver) ---- */
(function homeFX() {
  try {
  if (REDUCED || !document.documentElement || document.documentElement.dataset.saver === "1") return;
  // hero title: pointer-driven 3D tilt + layered depth shadow, eased
  const hero = document.getElementById("hero"), title = hero && hero.querySelector(".hero-title");
  if (title && matchMedia("(pointer: fine)").matches) {
    let tx = 0, ty = 0, cx = 0, cy = 0, raf2 = 0;
    const tick = () => {
      cx += (tx - cx) * 0.08; cy += (ty - cy) * 0.08;
      title.style.transform = `perspective(900px) rotateY(${(cx * 9).toFixed(2)}deg) rotateX(${(-cy * 6).toFixed(2)}deg)`;
      title.style.setProperty("--fx-dx", `${(-cx * 14).toFixed(1)}px`);
      title.style.setProperty("--fx-dy", `${(-cy * 10).toFixed(1)}px`);
      raf2 = Math.abs(tx - cx) + Math.abs(ty - cy) > 0.002 ? requestAnimationFrame(tick) : 0;
    };
    hero.addEventListener("pointermove", (e) => {
      const r = hero.getBoundingClientRect();
      tx = ((e.clientX - r.left) / r.width - 0.5) * 2; ty = ((e.clientY - r.top) / r.height - 0.5) * 2;
      if (!raf2) raf2 = requestAnimationFrame(tick);
    });
    hero.addEventListener("pointerleave", () => { tx = ty = 0; if (!raf2) raf2 = requestAnimationFrame(tick); });
    title.classList.add("fx-depth");
  }
  // stat cards: pointer position drives a glow that follows the cursor around the card edge,
  // plus a gentle 3D tilt (--tilt-x/--tilt-y consumed by gale.css)
  document.querySelectorAll(".stat-card, .rule-card, .dash-card").forEach((el) => {
    el.addEventListener("pointermove", (e) => {
      const r = el.getBoundingClientRect();
      const nx = (e.clientX - r.left) / r.width - 0.5;
      const ny = (e.clientY - r.top) / r.height - 0.5;
      el.style.setProperty("--gx", `${e.clientX - r.left}px`);
      el.style.setProperty("--gy", `${e.clientY - r.top}px`);
      el.style.setProperty("--tilt-y", `${(nx * 7).toFixed(2)}deg`);
      el.style.setProperty("--tilt-x", `${(-ny * 5).toFixed(2)}deg`);
    }, { passive: true });
    el.addEventListener("pointerleave", () => {
      el.style.setProperty("--tilt-x", "0deg");
      el.style.setProperty("--tilt-y", "0deg");
    }, { passive: true });
  });
  } catch { /* decoration only */ }
})();
